  if: inputs.use_secondary_drive_vm
  run: |
    node --input-type=module <<'NODE'
    import {requirePinnedPgRestoreMemory} from './scripts/run-official-local-storage-rehearsal.mjs';
    requirePinnedPgRestoreMemory('immutable-private-fresh-postgres', observed => {
      console.log(JSON.stringify(observed));
    });
    NODE

REHEARSAL_CUSTODIAL_BACKEND_PROOF_SECRET: ${{ !inputs.use_secondary_drive_vm && secrets.CUSTODIAL_BACKEND_PROOF_SECRET || '' }}
REHEARSAL_CUSTODIAL_NATIVE_ROUTE_PROOF_SECRET: ${{ !inputs.use_secondary_drive_vm && secrets.CUSTODIAL_NATIVE_ROUTE_PROOF_SECRET || '' }}
REHEARSAL_DEVICE_CREDENTIAL_SECRET: ${{ !inputs.use_secondary_drive_vm && secrets.DEVICE_CREDENTIAL_SECRET || '' }}
REHEARSAL_OPS_MANAGER_SESSION_SECRET: ${{ !inputs.use_secondary_drive_vm && secrets.OPS_MANAGER_SESSION_SECRET || '' }}

reverse_hunks.previous:
REHEARSAL_CUSTODIAL_BACKEND_PROOF_SECRET: ${{ secrets.CUSTODIAL_BACKEND_PROOF_SECRET }}
REHEARSAL_CUSTODIAL_NATIVE_ROUTE_PROOF_SECRET: ${{ secrets.CUSTODIAL_NATIVE_ROUTE_PROOF_SECRET }}
REHEARSAL_DEVICE_CREDENTIAL_SECRET: ${{ secrets.DEVICE_CREDENTIAL_SECRET }}
REHEARSAL_OPS_MANAGER_SESSION_SECRET: ${{ secrets.OPS_MANAGER_SESSION_SECRET }}

reverse_hunks.current:
const tmp=realpathSync(process.env.RUNNER_TEMP);
const secondaryVm=process.env.PRIVATE_REHEARSAL_SECONDARY_VM==='true';
if(secondaryVm){
  assert.equal(current429Capture,true);
  assert.equal(process.env.RUNNER_ENVIRONMENT,'self-hosted');
  assert.equal(process.env.RUNNER_NAME,'custodial-foundation-zorin');
  assert.equal(process.env.GITHUB_RUN_ATTEMPT,'1');
  const mount=dirname(tmp);
  const prefix='/mnt/actions-runner/.signed-current429.'+process.env.GITHUB_RUN_ID+'.';
  assert.ok(mount.startsWith(prefix)&&/^[a-zA-Z0-9]{8}\/encrypted$/.test(mount.slice(prefix.length)));
  assert.equal(tmp,resolve(mount,'work'));
  assert.equal(realpathSync(process.env.TMPDIR),resolve(mount,'process-tmp'));
  const scratchDevice=statSync(tmp).dev;
  assert.equal(statSync(process.env.TMPDIR).dev,scratchDevice);
  assert.equal(statSync('/mnt/docker').dev,scratchDevice);
  assert.equal(statSync('/var/lib/containerd').dev,scratchDevice);
  assert.notEqual(statSync('/mnt/actions-runner').dev,scratchDevice);
}
const owned=mkdtempSync(resolve(tmp,'private-backup-rehearsal-'));
